// Write-only password property
import java.util.Arrays;public class Q05 {public static class UserBean {private char[] password=new char[0];public UserBean(){}public void setPassword(String value){if(value==null)throw new IllegalArgumentException("Password required");Arrays.fill(password,'\0');password=value.toCharArray();}public boolean matchesPassword(String attempt){return Arrays.equals(password,attempt.toCharArray());}}public static void main(String[] args){UserBean u=new UserBean();u.setPassword("Demo123!");System.out.println("Matching sample: "+u.matchesPassword("Demo123!"));}}
